const $=id=>document.getElementById(id);let timer=null,stream=null,audio=null,micStream=null,audioFrame=null,motionTimer=null;
function line(parent,name,value){const div=document.createElement('div');div.className='sensor-row';const a=document.createElement('span'),b=document.createElement('b');a.textContent=name;b.textContent=value;div.append(a,b);parent.append(div)}
async function browserDevices(){if(!navigator.mediaDevices?.enumerateDevices)return;const list=await navigator.mediaDevices.enumerateDevices();for(const [id,kind]of [['audioSource','audioinput'],['cameraSource','videoinput']]){const selected=$(id).value;$(id).replaceChildren(new Option('Predeterminada del navegador',''));let i=0;for(const d of list.filter(d=>d.kind===kind))$(id).add(new Option(d.label||`Dispositivo ${++i} (permiso pendiente)`,d.deviceId));if([...$(id).options].some(o=>o.value===selected))$(id).value=selected;}}
async function scan(){try{const response=await fetch('/api/mac-sensors',{cache:'no-store'});if(!response.ok)throw Error();const d=await response.json();if(!d.available)throw Error();$('macStatus').textContent='Puente local conectado · '+new Date(d.timestamp*1000).toLocaleTimeString();$('deviceList').replaceChildren();for(const c of d.cameras)line($('deviceList'),'Cámara',c.name);for(const a of d.audio.filter(a=>a.input))line($('deviceList'),a.transport.includes('virtual')?'Entrada virtual':'Entrada de audio',a.name);for(const u of d.usb)line($('deviceList'),'USB detectado',u.name);for(const p of d.serial)line($('deviceList'),'Puerto · protocolo pendiente',p);if(!d.cameras.length)line($('deviceList'),'Cámaras en inventario','0');line($('deviceList'),'Alimentación',d.power);$('thermals').replaceChildren();for(const t of d.thermal)line($('thermals'),t.name,t.celsius.toFixed(2)+' °C');$('thermalSummary').textContent=d.thermal.length?`${d.thermal.length} canales · ${Math.min(...d.thermal.map(t=>t.celsius)).toFixed(1)}–${Math.max(...d.thermal.map(t=>t.celsius)).toFixed(1)} °C · `+new Date().toLocaleTimeString():'Sin lectura térmica disponible. No se estiman grados.';await browserDevices();}catch{$('macStatus').textContent='Puente local no disponible. Ejecuta npm start en la Mac. En la versión alojada solo funcionan sensores del navegador.';if(timer){clearInterval(timer);timer=null;$('thermalLive').textContent='▶ Actualizar cada 3 s';}}}
$('scanMac').onclick=scan;$('thermalLive').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('thermalLive').textContent='▶ Actualizar cada 3 s'}else{scan();timer=setInterval(scan,3000);$('thermalLive').textContent='■ Detener actualización'}};
function mediaError(e){return e.name==='NotAllowedError'?'Permiso denegado o bloqueado por el navegador.':e.name==='NotFoundError'?'No se encontró un dispositivo disponible.':'Dispositivo no disponible: '+e.name;}
function stopMic(){if(audioFrame)cancelAnimationFrame(audioFrame);micStream?.getTracks().forEach(t=>t.stop());audio?.close();micStream=null;audio=null;$('audioMeter').value=0;$('audioStatus').textContent='Audio detenido.'}
$('mic').onclick=async()=>{stopMic();try{if(!navigator.mediaDevices?.getUserMedia)throw {name:'NotSupportedError'};micStream=await navigator.mediaDevices.getUserMedia({audio:$('audioSource').value?{deviceId:{exact:$('audioSource').value}}:true});audio=new AudioContext();await audio.resume();const node=audio.createMediaStreamSource(micStream),analyser=audio.createAnalyser();analyser.fftSize=1024;node.connect(analyser);const samples=new Float32Array(analyser.fftSize);function tick(){analyser.getFloatTimeDomainData(samples);const rms=Math.sqrt(samples.reduce((sum,x)=>sum+x*x,0)/samples.length);$('audioMeter').value=rms;$('audioStatus').textContent=`REAL · RMS ${rms.toFixed(4)} · ${rms>0?(20*Math.log10(rms)).toFixed(1):'−∞'} dBFS · sin grabación`;audioFrame=requestAnimationFrame(tick)}tick();await browserDevices()}catch(e){stopMic();$('audioStatus').textContent=mediaError(e)}};$('micStop').onclick=stopMic;
function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null;$('cameraView').srcObject=null;$('cameraStatus').textContent='Cámara detenida.'}
$('camera').onclick=async()=>{stopCamera();try{if(!navigator.mediaDevices?.getUserMedia)throw {name:'NotSupportedError'};stream=await navigator.mediaDevices.getUserMedia({video:$('cameraSource').value?{deviceId:{exact:$('cameraSource').value}}:true,audio:false});$('cameraView').srcObject=stream;$('cameraStatus').textContent='REAL · video local · sin grabación';await browserDevices()}catch(e){$('cameraStatus').textContent=mediaError(e)}};$('cameraStop').onclick=stopCamera;
$('locate').onclick=()=>{if(!navigator.geolocation)return $('locationStatus').textContent='Ubicación no soportada en este navegador.';$('locationStatus').textContent='Solicitando ubicación del sistema…';navigator.geolocation.getCurrentPosition(p=>{$('locationStatus').textContent=`REAL · ${p.coords.latitude.toFixed(5)}, ${p.coords.longitude.toFixed(5)} · precisión ±${Math.round(p.coords.accuracy)} m · ${new Date(p.timestamp).toLocaleTimeString()} · origen del posicionamiento no identificado`},e=>{$('locationStatus').textContent={1:'Permiso de ubicación denegado.',2:'Ubicación no disponible.',3:'Tiempo de espera agotado.'}[e.code]||'Sin ubicación.'},{enableHighAccuracy:true,timeout:15000,maximumAge:0})};
let padEnabled=false;$('gamepadEnable').onclick=()=>{padEnabled=!padEnabled;$('gamepadEnable').textContent=padEnabled?'Desactivar mando':'Activar mando para conducir'};
setInterval(()=>{const p=[...(navigator.getGamepads?.()||[])].find(Boolean);$('gamepadStatus').textContent=p?`REAL · ${p.id} · ${padEnabled?'conducción activa':'solo detectado'}`:'Sin mando detectado; pulsa un botón del mando.';document.dispatchEvent(new CustomEvent('sentinel-gamepad',{detail:padEnabled&&p&&!document.hidden?{forward:Math.abs(p.axes[1]||0)>.15?-(p.axes[1]||0):0,turn:Math.abs(p.axes[0]||0)>.15?p.axes[0]||0:0,stop:!!p.buttons[1]?.pressed}:{forward:0,turn:0}}))},100);
function motionEvent(e){const a=e.accelerationIncludingGravity,r=e.rotationRate;if(a&&[a.x,a.y,a.z].some(Number.isFinite)){$('motionStatus').textContent=`REAL · aceleración con gravedad: ${[a.x,a.y,a.z].map(n=>n==null?'—':n.toFixed(2)).join(', ')} m/s² · giro: ${[r?.alpha,r?.beta,r?.gamma].map(n=>n==null?'—':n.toFixed(2)).join(', ')} °/s`;clearTimeout(motionTimer)}}
$('motion').onclick=async()=>{try{if(!('DeviceMotionEvent'in window))return $('motionStatus').textContent='API de movimiento no disponible.';if(typeof DeviceMotionEvent.requestPermission==='function'&&await DeviceMotionEvent.requestPermission()!=='granted')return $('motionStatus').textContent='Permiso de movimiento denegado.';window.removeEventListener('devicemotion',motionEvent);window.addEventListener('devicemotion',motionEvent);$('motionStatus').textContent='Esperando lecturas reales…';clearTimeout(motionTimer);motionTimer=setTimeout(()=>{$('motionStatus').textContent='Sin datos de movimiento: API presente no implica sensor físico disponible.'},4000)}catch(e){$('motionStatus').textContent='Movimiento no disponible: '+e.name}};
addEventListener('pagehide',()=>{stopMic();stopCamera();clearInterval(timer);window.removeEventListener('devicemotion',motionEvent)});navigator.mediaDevices?.addEventListener('devicechange',()=>browserDevices().catch(()=>{}));browserDevices().catch(()=>{});
let externalTimer=null;async function external(){try{const r=await fetch('/api/external-sensors',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();if(!Array.isArray(d.samples))throw Error();$('externalSamples').replaceChildren();for(const sample of d.samples){const age=Math.max(0,d.timestamp-sample.received_at);line($('externalSamples'),sample.sensor_id+' · '+sample.model,age>5?'CADUCADO · '+age.toFixed(0)+' s':'EXTERNO · sin calibrar');for(const m of sample.metrics)line($('externalSamples'),m.name,m.value+' '+m.unit)}$('externalStatus').textContent=d.samples.length?`${d.samples.length} sensores · caducidad visual 5 s · `+new Date().toLocaleTimeString():'Sin muestras. Inicia un adaptador local con tu sensor.';}catch{$('externalStatus').textContent='Adaptadores disponibles en el servidor local (npm start).'}}$('externalRefresh').onclick=external;$('externalLive').onclick=()=>{if(externalTimer){clearInterval(externalTimer);externalTimer=null;$('externalLive').textContent='▶ Supervisar cada 2 s'}else{external();externalTimer=setInterval(external,2000);$('externalLive').textContent='■ Detener supervisión'}};addEventListener('pagehide',()=>clearInterval(externalTimer));
